  [1, 0, 1, 0, 1, 0, 1, 0]
];

// Draw squares
for (let row = 0; row < 8; row++) {
  for (let col = 0; col < 8; col++) {
    if ((row + col) % 2 === 0) {
      ctx.fillStyle = '#FFFFFF'; // White square
    } else {
      ctx.fillStyle = '#000000'; // Black square
    }
    ctx.fillRect(col * squareSize, row * squareSize, squareSize, squareSize);

    // Draw checker pattern
    if (board[row][col] === 1) {
      ctx.fillStyle = '#FF0000'; // Red checker
    } else {
      ctx.fillStyle = '#0000FF'; // Blue checker
    }
    ctx.beginPath();
    ctx.arc(col * squareSize + squareSize/2, row * squareSize + squareSize/2, squareSize/4, 0, Math.PI * 2);
    ctx.fill();
  }
}

