    ctx.fill();
}

// Draw jellyfish body
const cx = W / 2;
const cy = H * 0.7;
const radius = 40;

// Main body
ctx.fillStyle = '#4a7ec0';
ctx.beginPath();
ctx.arc(cx, cy, radius, 0, Math.PI * 2);
ctx.fill();

// Tentacles
ctx.fillStyle = '#3a6090';
for(let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const length = 60 + Math.random() * 30;

    const startX = cx + Math.cos(angle) * radius;
    const startY = cy + Math.sin(angle) * radius;

    ctx.beginPath();
    ctx.moveTo(startX, startY);

    const endX = startX + Math.cos(angle) * length;
    const endY = startY + Math.sin(angle) * length;

    ctx.lineTo(endX, endY);

    // Tentacle waves
    const waveOffset = Date.now() / 1000 * i * 0.5;
    const waveLength = 10 + Math.random() * 20;
    const waveCount = 3 + Math.random() * 2;

    for(let j = 0; j < waveCount; j++) {
        const waveAngle = (j / waveCount) * Math.PI * 2 + waveOffset;
        const waveX = endX + Math.cos(waveAngle) * waveLength;
        const waveY = endY + Math.sin(waveAngle) * waveLength;

        ctx.lineTo(waveX, waveY);
    }

    ctx.lineTo(endX, endY);
    ctx.closePath();
    ctx.fill();
}

// Glow effect - soft gradient around jellyfish
const gradient = ctx.createRadialGradient(
    cx, cy, 0,
    cx, cy, radius * 1.5
);
gradient.addColorStop(0, 'rgba(74, 124, 188, 0.3)');
gradient.addColorStop(0.7, 'rgba(50, 90, 140, 0.1)');
gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');

ctx.fillStyle = gradient;
ctx.beginPath();
ctx.arc(cx, cy, radius * 1.5, 0, Math.PI * 2);
ctx.fill();

// Add some ambient glow
ctx.globalAlpha = 0.1;
ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
for(let i = 0; i < 15; i++) {
    const x = cx + Math.random() * radius * 2 - radius;
    const y = cy + Math.random() * radius * 2 - radius;
    const size = 20 + Math.random() * 40;
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fill();
}
ctx.globalAlpha = 1.0;

