    const angle = i * 0.5;
    const x = 200 + Math.cos(angle) * radius;
    const y = 250 + Math.sin(angle) * radius;
    if (i === 0) {
        ctx.moveTo(x, y);
    } else {
        ctx.lineTo(x, y);
    }
    radius += 5;
}
ctx.closePath();
ctx.fill();

